1	// Invoice rendering for the customer portal.
2	
3	export interface Line {
4	  description: string;
5	  cents: number;
6	}
7	
8	function formatMoney(cents: number): string {
9	  const sign = cents < 0 ? "-" : "";
10	  const abs = Math.abs(cents);
11	  const whole = Math.floor(abs / 100).toLocaleString("en-US");
12	  const frac = String(abs % 100).padStart(2, "0");
13	  return `${sign}$${whole}.${frac}`;
14	}
15	
16	export function renderInvoice(lines: Line[]): string {
17	  const rows = lines.map((l) => `${l.description.padEnd(20)} ${formatMoney(l.cents).padStart(12)}`);
18	  const total = lines.reduce((sum, l) => sum + l.cents, 0);
19	  rows.push(`${"TOTAL".padEnd(20)} ${formatMoney(total).padStart(12)}`);
20	  return rows.join("\n");
21	}
