1	// Receipt rendering for the point-of-sale printer.
2	
3	export interface ReceiptItem {
4	  name: string;
5	  cents: number;
6	}
7	
8	function formatMoney(cents: number): string {
9	  const whole = Math.floor(cents / 100).toLocaleString("en-US");
10	  const frac = String(Math.abs(cents) % 100).padStart(2, "0");
11	  return `$${whole}.${frac}`;
12	}
13	
14	export function renderReceipt(items: ReceiptItem[]): string {
15	  const rows = items.map((i) => `${i.name.padEnd(16)}${formatMoney(i.cents).padStart(10)}`);
16	  const total = items.reduce((sum, i) => sum + i.cents, 0);
17	  rows.push("-".repeat(26));
18	  rows.push(`${"Total".padEnd(16)}${formatMoney(total).padStart(10)}`);
19	  return rows.join("\n");
20	}
