1	// Finance export, consumed by the quarterly reconciliation spreadsheet.
2	// The column layout and number format are frozen; finance diffs the
3	// output against last quarter's file.
4	
5	export interface ReportRow {
6	  account: string;
7	  cents: number;
8	}
9	
10	function fmt(cents: number): string {
11	  return "$" + (cents / 100).toFixed(2);
12	}
13	
14	export function renderReport(rows: ReportRow[]): string {
15	  const out = ["account,amount"];
16	  for (const r of rows) out.push(`${r.account},${fmt(r.cents)}`);
17	  return out.join("\n");
18	}
